const first = findPages(toPdf(p1));
if (first.pages['Введение'] !== 3) throw new Error('Титульный лист или содержание заняли больше одной страницы: введение на странице ' + first.pages['Введение']);
const finalDocx = join(here, `${OUT_NAME}.docx`);
writeFileSync(finalDocx, await Packer.toBuffer(build(first.pages)));
const check = findPages(toPdf(finalDocx));
const moved = TOC.filter(([t]) => first.pages[t] !== check.pages[t]);
if (moved.length) console.warn('Внимание: после второго прохода сместились страницы:', moved.map(([t]) => t));
console.log('Страниц:', check.n, '\nСодержание:', check.pages);
console.log('Готово:', finalDocx);
